import{_ as a,C as l,o as i,c as n,ak as r,E as o,j as t,a as c}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"Log 日志","description":"","frontmatter":{},"headers":[],"relativePath":"components/log.md","filePath":"components/log.md","lastUpdated":1790414471000}'),h={name:"components/log.md"};function s(g,d,b,u,p,f){const e=l("XhDemo");return i(),n("div",null,[d[0]||(d[0]=r('<h1 id="log-日志" tabindex="-1">Log 日志 <a class="header-anchor" href="#log-日志" aria-label="Permalink to &quot;Log 日志&quot;">​</a></h1><p>等宽排版的滚动区域，一行一条，可以自动跟随到底部。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/log" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/log.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/log" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/log" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/log.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>root / viewport / content / line 四层；一行写什么由作者决定，组件只提供身份与等宽排版</p>',5)),o(e,{src:"log/01-basic"}),d[1]||(d[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;log&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>line</code> · <code>scroll-to-end-trigger</code> · <code>live-region</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="按行数定高" tabindex="-1">按行数定高 <a class="header-anchor" href="#按行数定高" aria-label="Permalink to &quot;按行数定高&quot;">​</a></h3><p>rows 决定可见几行，一行的高度归皮肤，修改 --xh-log-line-height 两者一起变化</p>',6)),o(e,{src:"log/02-rows"}),d[2]||(d[2]=t("h3",{id:"自动跟随到底部",tabindex:"-1"},[c("自动跟随到底部 "),t("a",{class:"header-anchor",href:"#自动跟随到底部","aria-label":'Permalink to "自动跟随到底部"'},"​")],-1)),d[3]||(d[3]=t("p",null,"新行进入时视口自动跟随；向上滚动一段即停止跟随，组件报告的 atBottom 与 scrollToBottom 足以自行绘制一条回到最新",-1)),o(e,{src:"log/03-follow"}),d[4]||(d[4]=t("h3",{id:"取行中",tabindex:"-1"},[c("取行中 "),t("a",{class:"header-anchor",href:"#取行中","aria-label":'Permalink to "取行中"'},"​")],-1)),d[5]||(d[5]=t("p",null,"loading 使日志区报告 aria-busy 并把指针换为忙碌态；正在拉取那一行由作者自行渲染",-1)),o(e,{src:"log/04-loading"}),d[6]||(d[6]=t("h3",{id:"级别",tabindex:"-1"},[c("级别 "),t("a",{class:"header-anchor",href:"#级别","aria-label":'Permalink to "级别"'},"​")],-1)),d[7]||(d[7]=t("p",null,"行上写 level，四档 debug / info / warn / error 由皮肤染色；时间戳与行内标记仍归作者",-1)),o(e,{src:"log/05-levels"}),d[8]||(d[8]=t("h3",{id:"换为自绘滚动条",tabindex:"-1"},[c("换为自绘滚动条 "),t("a",{class:"header-anchor",href:"#换为自绘滚动条","aria-label":'Permalink to "换为自绘滚动条"'},"​")],-1)),d[9]||(d[9]=t("p",null,"视口提供一个 id，用滚动条的 controls 挂载；滚动条浮在内容之上，不占宽度也不留空道",-1)),o(e,{src:"log/06-scrollbar"}),d[10]||(d[10]=t("h3",{id:"回到底部与播报",tabindex:"-1"},[c("回到底部与播报 "),t("a",{class:"header-anchor",href:"#回到底部与播报","aria-label":'Permalink to "回到底部与播报"'},"​")],-1)),d[11]||(d[11]=t("p",null,"向上翻一段，右下角的按钮自动显示，按下后归位并重新粘附；输出结束后在播报区朗读一句结论",-1)),o(e,{src:"log/07-scroll-button"}),d[12]||(d[12]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>构建输出、运行日志、命令行回显。</li><li>任何从底部持续增长、需要始终跟随到底的内容：内容不需要区分条目身份，整段追加即可。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容是会话、条目有身份且需要逐条遍历时，使用<a href="./message-feed">消息流</a>。</li><li>展示结构化记录、需要筛选排序时，使用<a href="./table">表格</a>。</li><li>展示一段代码时，使用<a href="./code-view">代码视图</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>结构四层：<code>root</code> · <code>viewport</code> · <code>content</code> · <code>line</code>；每行内容由作者决定，组件只提供身份与等宽排版。另有两个可选部件：<code>scroll-to-end-trigger</code> 与 <code>live-region</code>。</li><li><code>rows</code> 按行数定高。</li><li>自动跟随到底部；用户向上翻时停止跟随，回到底部后恢复。</li><li>内置“回到底部”：离开底部时出现，按下后归位并重新粘附。留空时皮肤绘制向下的字形，放入节点即替换为自定义图形。</li><li>应用设为 <code>data-material=&quot;liquid&quot;</code> 时，“回到底部”换成液态面：按下层换色调，按住时液面随手指形变。</li><li>视口自身可聚焦，整块日志占一个 Tab 停靠位，方向键与翻页键交给浏览器滚动。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>行内可以用<a href="./highlight">文本高亮</a>标出关键词。</li><li>给视口一个 id，把<a href="./scrollbar">滚动条</a>的 <code>controls</code> 指向它，滚动条与视口平级放在 <code>root</code> 内：它浮在内容之上，不占宽度。未挂自绘滚动条时视口自行预留一条通道，原生滚动条出现与消失不会推动文字。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>用户向上翻时不强行拉回底部。</li><li>行数很大时截断或虚拟化，不把十万行全部挂载。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>每到一行就整块重渲。</li><li>不提供复制或下载全部日志的入口。</li><li>把每一行都写进播报区，读屏会被逐行打断。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-log&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLogContent</code> <code>XhLogLine</code> <code>XhLogLiveRegion</code> <code>XhLogRoot</code> <code>XhLogScrollToEndTrigger</code> <code>XhLogViewport</code></td></tr><tr><td>组合式函数</td><td><code>useLog</code></td></tr><tr><td>状态机</td><td><code>logMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/log.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>threshold</code></td><td><code>number</code></td><td></td><td>距底部多少 px 视为在底部，默认使用贴底原语的默认值。</td></tr><tr><td><code>onStickChange</code></td><td><code>(details: LogStickChangeDetails) =&gt; void</code></td><td></td><td>贴底状态变化时通知宿主。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>行仍在传输中：日志区报告 aria-busy，根写 data-loading。</td></tr><tr><td><code>rows</code></td><td><code>number</code></td><td></td><td>视口按多少行定高；未提供时高度由皮肤决定。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。影响行文字号与内衬，行高不随档位变化。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;LogTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>LogStickChangeDetails</code></td><td>贴底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLogRoot</code></td><td><code>default</code></td><td><code>LogRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLogLine</code></td><td><code>level</code></td><td><code>LogLevel</code></td><td></td><td>该行的级别，写为行上的 data-level。</td></tr><tr><td><code>XhLogRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;LogRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>scroll-to-end-trigger</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STICK.CHANGE</code> · <code>SCROLL_TO_BOTTOM</code> · <code>PRESS.START</code> · <code>PRESS.END</code> · <code>TRIGGER.RENDERED</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>rows</code></td><td><code>number | undefined</code></td><td>取整后的行数；rows 缺席或不是正数时为 undefined。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td>当前滚动位置是否落在底部阈值内。</td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td>新行到达时是否自动跟随到底部。</td></tr><tr><td><code>showScrollToEndTrigger</code></td><td><code>boolean</code></td><td>是否显示回到底部按钮，不在底部时为 true。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td>滚动到底部并恢复贴附。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineProps</code></td><td><code>(props?: LogLineProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollToEndTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/structural-roles/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>焦点进入日志区</td><td>日志区自身可聚焦，方向键/PageUp/PageDown/Home/End 交给浏览器滚动，组件不接管</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>焦点在&quot;回到底部&quot;按钮上</td><td>滚回底部并重新粘附</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>按住&quot;回到底部&quot;按钮且视口不在底部</td><td>按住期间 scroll-to-end-trigger 投影 data-pressed，与指针 :active 同一副按压面；抬起、失焦或回到底部（按钮收起）撤下</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>viewport</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>viewport</code></td><td><code>aria-label</code></td><td>label.log</td></tr><tr><td><code>viewport</code></td><td><code>aria-live</code></td><td>&#39;off&#39;</td></tr><tr><td><code>viewport</code></td><td><code>role</code></td><td>&#39;log&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>aria-label</code></td><td>label.scrollToBottom</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><ul><li>视口是 <code>role=log</code>，但其隐含的 <code>aria-live</code> 被显式关闭：逐行读出连续输出会成为读屏噪声。</li><li>播报使用独立的 <code>live-region</code>：宿主决定读哪一句、何时读，例如一段输出结束后读出结论与错误条数。不要把每一行原样写入，否则等于重新打开逐行播报。</li><li>成批取行期间视口报告 <code>aria-busy</code>；播报区是视口的兄弟节点，不受其影响。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/log.css</code> 使用 <code>[data-scope=&quot;log&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-at-bottom</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-sticking</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>line</code></td><td><code>data-level</code></td><td>line?.level</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-profile</code></td><td>&#39;floating&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-liquid</code></td><td>&#39;&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-material</code></td><td>&#39;frosted&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-log-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>log 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-log-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>log 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-log-content-px</code></td><td><code>content</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_log-content-px</code></td><td>log 的 content 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-log-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>log 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-font</code></td><td><code>content</code></td><td><code>font-family</code></td><td><code>default</code></td><td><code>--xh-font-family-mono</code></td><td>log 的 content 部件 font-family 覆盖槽。</td></tr><tr><td><code>--xh-log-font-size</code></td><td><code>content</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_log-font-size</code></td><td>log 的 content 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-log-icon-size</code></td><td><code>scroll-to-end-trigger</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-glyph-size</code></td><td>log 的 scroll-to-end-trigger 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-log-level-debug-fg</code></td><td><code>line</code></td><td><code>color</code></td><td><code>level=debug</code></td><td><code>--xh-fg-subtle</code></td><td>log 的 line 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-level-error-fg</code></td><td><code>line</code></td><td><code>color</code></td><td><code>level=error</code></td><td><code>--xh-fg-danger</code></td><td>log 的 line 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-level-info-fg</code></td><td><code>line</code></td><td><code>color</code></td><td><code>level=info</code></td><td><code>--xh-fg-default</code></td><td>log 的 line 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-level-warn-fg</code></td><td><code>line</code></td><td><code>color</code></td><td><code>level=warn</code></td><td><code>--xh-fg-warning</code></td><td>log 的 line 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-line-height</code></td><td><code>line</code><br><code>root</code><br><code>viewport</code></td><td><code>block-size</code><br><code>line-height</code></td><td><code>default</code></td><td><code>1.25rem</code></td><td>log 的 line、root、viewport 部件 block-size、line-height 覆盖槽。</td></tr><tr><td><code>--xh-log-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>log 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-log-rows</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>16</code></td><td>log 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-bg</code></td><td><code>scroll-to-end-trigger</code></td><td><code>--xh-ink-surface</code><br><code>background-color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>xh-ink-surface</code></td><td><code>--xh-_material-bg</code><br><code>--xh-_material-bg-focus</code></td><td>log 的 scroll-to-end-trigger 部件 --xh-ink-surface、background-color 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-bg-hover</code></td><td><code>scroll-to-end-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-_material-bg-hover</code></td><td>log 的 scroll-to-end-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-border</code></td><td><code>scroll-to-end-trigger</code></td><td><code>border</code><br><code>border-color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-border</code></td><td>log 的 scroll-to-end-trigger 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-fg</code></td><td><code>scroll-to-end-trigger</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-fg</code></td><td>log 的 scroll-to-end-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-inset</code></td><td><code>scroll-to-end-trigger</code></td><td><code>inset-block-end</code><br><code>inset-inline-end</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>log 的 scroll-to-end-trigger 部件 inset-block-end、inset-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-radius</code></td><td><code>scroll-to-end-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-circle</code></td><td>log 的 scroll-to-end-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-shadow</code></td><td><code>scroll-to-end-trigger</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-shadow</code></td><td>log 的 scroll-to-end-trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-log-scroll-to-end-trigger-size</code></td><td><code>scroll-to-end-trigger</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code><br><code>xh-action-profile=floating</code></td><td><code>--xh-_action-profile-visual-size</code></td><td>log 的 scroll-to-end-trigger 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-log-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>none</code></td><td>log 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-log-tab-size</code></td><td><code>line</code></td><td><code>tab-size</code></td><td><code>default</code></td><td><code>4</code></td><td>log 的 line 部件 tab-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态 · 出现（锚定面板） · 出现（无锚定弹出）（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',60))])}const q=a(h,[["render",s]]);export{m as __pageData,q as default};
